for row in cm['core_passages']:
 for a in row['actually_asked_coverage']:a['asked_facts']=sm[a['question_id']]['asked_facts'];a['scope_reference']='asked-clause-map.json#'+a['question_id']
cm['RR_complete_reconciliation']=json.loads((R/'independent-source-reconciliation.json').read_text());cm['warning']='Only actual asked facts earn coverage, never contextual background. Reference-only questions earn no novelty credit.';(V/'coverage-map.json').write_text(json.dumps(cm,indent=2,ensure_ascii=False)+'\n')
