(V/'question-bank.md').write_text('\n\n'.join(parts)+'\n');(V/'version-changes.json').write_text(json.dumps({'from':'candidate-v3','to':'candidate-v4','question_entries_unchanged':True,'key_entries_unchanged':True,'scope_only_corrections':['Q85','Q89'],'count':92,'novelty_credit_count':89,'reference_only_ids':['Q68','Q73','Q76'],'old_history_preserved':True},indent=2)+'\n');(V/'input-manifest.json').write_text(json.dumps({'status':'candidate frozen for NEW unexposed independent source/scope challenge; not overall completion','question_count':92,'hashes':{n:hashlib.sha256((V/n).read_bytes()).hexdigest() for n in ['questions.json','answer-key.json','asked-clause-map.json','coverage-map.json','coverage-ledger.json','question-bank.md','version-changes.json']},'frozen_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()},indent=2)+'\n')
p=B/'progress.json';s=json.loads(p.read_text());s['candidate_bank_path']=str(V.resolve());s['phase']='seed_passed92_coverage_unexposed_recheck_scope_pending';s['coverage_review']['post_draft_exposure']={'report':str((R/'independence-deviation.json').resolve()),'treatment':'Preserved; not final unexposed signoff. Scope corrections only; questions/outcomes unchanged.'};s['coverage_review']['NEW_challenge']='to_dispatch_candidate-v4';p.write_text(json.dumps(s,indent=2)+'\n');print('Candidatev4frozen92 unchanged question/keyrecords; actual asked scope normalized.')
